
import json
import inspect


class AgentExecutor:

    def __init__(self, registry):
        self.registry = registry

    def execute(self, decision):

        tool_name = decision.tool_name

        try:
            # Parse the JSON arguments generated by Gemini
            arguments = json.loads(decision.tool_args)

            if not isinstance(arguments, dict):
                raise ValueError(
                    "Tool arguments must be a JSON object."
                )

            # Check whether the selected tool exists
            tool = self.registry.tools.get(tool_name)

            if tool is None:
                raise ValueError(
                    f"Tool '{tool_name}' is not registered."
                )

            # Validate function parameters
            signature = inspect.signature(tool["function"])

            allowed = set(signature.parameters.keys())
            supplied = set(arguments.keys())

            unknown = supplied - allowed

            if unknown:
                raise ValueError(
                    f"Unexpected arguments: {unknown}"
                )

            # Execute the selected tool
            result = self.registry.execute(
                tool_name,
                arguments
            )

            return {
                "success": True,
                "tool": tool_name,
                "result": result
            }

        except Exception as error:

            return {
                "success": False,
                "tool": tool_name,
                "error": str(error)
            }
